 @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");static JdbcTemplate jdbc;
 final ObjectMapper json=new ObjectMapper();ReservationStore db;ReservationOrders orders;ReservationSlots slots;ReservationExpiry expiry;PaymentService payments;CouponInventory inventory;CouponTransactions coupons;CouponServiceRedemption service;MerchantActor shop,other,staff;VehicleOwner owner,peer;Time clock;
 static class Time extends Clock {Instant value=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return value;}}
 @BeforeAll static void schema()throws Exception{var ds=new DriverManagerDataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());jdbc=new JdbcTemplate(ds);try(var c=ds.getConnection();var paths=Files.list(Path.of("..","docs","sql","migrations"))){for(var p:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(p));ScriptUtils.executeSqlScript(c,new FileSystemResource(Path.of("..","docs","sql","migrations","V039__coupon_transactions.sql")));}assertEquals(88,jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='BASE TABLE'",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM order_coupon_allocation",Integer.class));}
 @BeforeEach void setup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_coupon_transaction");for(String t:List.of("coupon_service_redemption","coupon_service_authorization","coupon_transaction_event","order_coupon_allocation","coupon_stock_event","coupon_issue","coupon_publication","coupon_source","user_coupon","coupon","merchant_commission_entry","order_commission_snapshot","merchant_commission_policy","merchant_application_review","merchant_application","refund_event","refund","order_redemption","order_status_transition","payment_event","payment_exception","payment","order","appointment_slot","merchant_project_version","merchant_project","standard_project","staff_account","merchant","vehicle","user","operator_account","auth_session","auth_rate_limit","audit_log","idempotency_record"))jdbc.update("DELETE FROM `"+t+"`");clock=new Time();var manager=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,json,new WriteIntegrityService(jdbc,json,manager),clock,manager);expiry=new ReservationExpiry(db);orders=new ReservationOrders(db,expiry);slots=new ReservationSlots(db);payments=new PaymentService(db,expiry,new PaymentChannels(new LocalTestPaymentChannel(LocalTestPaymentChannelTest.KEY,clock)));inventory=new CouponInventory(db,new OperatorIdentity(jdbc,null,manager));coupons=new CouponTransactions(db);service=new CouponServiceRedemption(db);jdbc.update("INSERT INTO merchant(id,merchant_type,name,address,status) VALUES(1,2,'synthetic-A','test',1),(2,2,'synthetic-B','test',1)");jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account,status) VALUES(1,1,'MERCHANT','coupon-A','ACTIVE'),(2,2,'MERCHANT','coupon-B','ACTIVE'),(3,1,'STAFF','coupon-staff','ACTIVE')");jdbc.update("INSERT INTO user(id,openid,status) VALUES(1,'coupon-owner',1),(2,'coupon-peer',1)");jdbc.update("INSERT INTO vehicle(id,user_id,model_id) VALUES(1,1,1),(2,2,1)");jdbc.update("INSERT INTO standard_project(id,category,project_name,service_content,base_price_low,base_price_high,status) VALUES(1,1,'synthetic-project','synthetic',1,100,1)");jdbc.update("INSERT INTO merchant_project(id,merchant_id,project_id,price,on_shelf) VALUES(1,1,1,12.34,1),(2,2,1,12.34,1)");jdbc.update("INSERT INTO merchant_project_version(id,merchant_project_id,version,price,on_shelf,actor_staff_id) VALUES(1,1,1,12.34,1,1),(2,2,1,12.34,1,2)");shop=new MerchantActor(1,1,session(1,"staff_account","MERCHANT","merchant-account",1L),Instant.now().plusSeconds(36000));other=new MerchantActor(2,2,session(2,"staff_account","MERCHANT","merchant-account",2L),Instant.now().plusSeconds(36000));staff=new MerchantActor(3,1,"STAFF",session(3,"staff_account","STAFF","merchant-account",1L),Instant.now().plusSeconds(36000));owner=new VehicleOwner(1,session(1,"user","OWNER","test-app",null),Instant.now().plusSeconds(36000));peer=new VehicleOwner(2,session(2,"user","OWNER","test-app",null),Instant.now().plusSeconds(36000));}
 String key(){return UUID.randomUUID().toString();}String session(long id,String type,String role,String app,Long merchant){String k=key();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,merchant_id,refresh_hash,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 10 HOUR))",k,type,id,role,app,merchant,key());return k;}
 int count(String t){return jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"`",Integer.class);}int code(Runnable r){return assertThrows(ResponseStatusException.class,r::run).getStatusCode().value();}
 ObjectNode terms(String type,String amount,String minimum,int seconds){return json.createObjectNode().put("name","合成交易券").put("type",type).put("project_id",1).put("amount",amount).put("min_spend",minimum).put("total_quantity",100).put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(seconds).toString());}
 long issue(VehicleOwner a,String type,String amount,String minimum,int seconds){var b=json.createObjectNode();b.set("terms",terms(type,amount,minimum,seconds));long c=inventory.create(shop,key(),b).path("data").path("coupon_id").longValue();inventory.status(shop,c,key(),json.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));return inventory.claim(a,key(),json.createObjectNode().put("coupon_id",c).put("publication_revision",2)).path("data").path("user_coupon_id").longValue();}
 long discount(){return issue(owner,"DISCOUNT","5.00","10.00",3600);}long voucher(){return issue(owner,"SERVICE","0.00","0.00",3600);}
 long slot(int capacity){Instant start=clock.value.atZone(ReservationInput.ZONE).toLocalDate().plusDays(1).atTime(10,0).atZone(ReservationInput.ZONE).toInstant();return slots.publish(shop,key(),new ReservationInput.Slot(1,start,start.plusSeconds(3600),capacity)).path("data").path("slot_id").longValue();}
 ObjectNode createBody(VehicleOwner a,long s,long uc){return json.createObjectNode().put("merchant_project_id",1).put("quote_version_id",1).put("vehicle_id",a.id()).put("slot_id",s).put("user_coupon_id",uc).put("publication_revision",2).put("rule_version",CouponTransactions.CASH_RULE);}
 long book(VehicleOwner a,long s,long uc){return orders.createCoupon(a,key(),CouponOrderInput.create(createBody(a,s,uc).toString())).path("data").path("order_id").longValue();}
 ObjectNode previewBody(VehicleOwner a,long s,Long uc,int page){var b=json.createObjectNode().put("merchant_project_id",1).put("quote_version_id",1).put("vehicle_id",a.id()).put("slot_id",s).put("page",page);if(uc==null)b.putNull("selected_user_coupon_id");else b.put("selected_user_coupon_id",uc);return b;}
 String couponState(long uc){return jdbc.queryForObject("SELECT status FROM user_coupon WHERE id=?",String.class,uc);}String allocation(long o){return jdbc.queryForObject("SELECT state FROM order_coupon_allocation WHERE order_id=?",String.class,o);}
 long pay(long o){return payments.create(owner,key(),o,"LOCAL_TEST").path("data").path("payment_id").longValue();}PaymentNotice notice(long p,String event,String status){var r=jdbc.queryForMap("SELECT p.amount,o.order_no FROM payment p JOIN `order` o ON o.id=p.order_id WHERE p.id=?",p);return new PaymentNotice(event,p,"synthetic-"+p,status,(BigDecimal)r.get("amount"),"CNY",r.get("order_no").toString(),clock.value,event+status);}
 long paid(long uc){long o=book(owner,slot(2),uc),p=pay(o);payments.notify(notice(p,key(),"SUCCEEDED"));return o;}
 OrderRefunds refunds(){return new OrderRefunds(db,payments,new RefundChannels(new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,clock,"")));}
 long request(long o){return refunds().request(owner,key(),o,"合成全额取消退款").path("data").path("refund").path("refund_id").longValue();}void approve(long o){refunds().decide(shop,key(),o,1,"ACCEPT",null);}
 RefundChannel.Notice refundNotice(long r,String event,String state){var row=jdbc.queryForMap("SELECT * FROM refund WHERE id=?",r);return new RefundChannel.Notice(event,r,row.get("refund_no").toString(),ReservationStore.number(row,"payment_id"),"synthetic-refund-"+r,state,(BigDecimal)row.get("amount"),"CNY",clock.value,event+state);}
 RefundRecovery refundWorker(java.util.function.Function<RefundChannel.Request,RefundChannel.Result> q){var adapter=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,clock,""){public boolean canTransact(){return true;}public Result query(Request request){assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return q.apply(request);}public Result submit(Request request){fail("已知退款不应重复提交");return null;}};return new RefundRecovery(new OrderRefunds(db,payments,new RefundChannels(adapter)),true);}
 ObjectNode authorize(long uc,long revision){return (ObjectNode)service.generate(owner,uc,key(),json.createObjectNode().put("expected_revision",revision)).get("data");}ObjectNode redeemBody(ObjectNode a){return json.createObjectNode().put("user_coupon_id",a.get("user_coupon_id").longValue()).put("authorization_revision",a.get("authorization_revision").longValue()).put("code",a.get("code").textValue());}
 @Test void previewAndBookingFreezeServerAmountAndSingleActiveContract(){long uc=discount(),s=slot(2);var result=json.valueToTree(coupons.preview(owner,previewBody(owner,s,uc,1)));assertTrue(result.path("can_create").asBoolean());assertEquals("7.34",result.path("selected").path("cash_amount").asText());assertEquals(0,count("order_coupon_allocation"));String k=key();var input=CouponOrderInput.create(createBody(owner,s,uc).toString());var first=orders.createCoupon(owner,k,input);long o=first.path("data").path("order_id").longValue();assertEquals(first,orders.createCoupon(owner,k,input));assertEquals("7.34",orders.detail(owner,o).get("amount_due"));assertEquals("RESERVED",couponState(uc));assertEquals(409,code(()->book(owner,s,uc)));assertEquals(1,count("order_coupon_allocation"));assertEquals(1,count("coupon_transaction_event"));assertEquals("7.34",jdbc.queryForObject("SELECT base_amount FROM order_commission_snapshot WHERE order_id=?",BigDecimal.class,o).toPlainString());}
