 List<Integer> race(List<Runnable> tasks)throws Exception{var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var results=new ArrayList<Future<Integer>>();for(var r:tasks)results.add(pool.submit(()->{start.await();try{r.run();return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:results)codes.add(f.get(40,TimeUnit.SECONDS));Collections.sort(codes);return codes;}finally{pool.shutdownNow();}}
