 void failEvent(String kind){jdbc.execute("CREATE TRIGGER fail_coupon_transaction BEFORE INSERT ON coupon_transaction_event FOR EACH ROW BEGIN IF NEW.kind='"+kind+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'; END IF; END");}
