 @Test void serviceAuthorizationRedemptionAndImmutableZeroCommissionReceipt(){long uc=voucher();var a=authorize(uc,0);var b=redeemBody(a);String k=key();var receipt=service.redeem(staff,k,b);assertEquals(receipt,service.redeem(staff,k,b));service.redeem(shop,key(),b);assertEquals("USED",couponState(uc));assertEquals(1,count("coupon_service_redemption"));assertEquals("0.00",receipt.path("data").path("commission_amount").asText());assertEquals(0,count("payment"));assertEquals(0,count("order"));assertEquals(0,count("merchant_commission_entry"));assertEquals(1,count("coupon_transaction_event"));assertFalse(json.valueToTree(service.view(owner,uc)).has("code"));assertFalse(jdbc.queryForObject("SELECT after_state FROM audit_log WHERE action='COUPON_SERVICE_AUTHORIZE'",String.class).contains(a.get("code").textValue()));}
