 @Test void serviceWrongCodeRateLimitPersistsAndResetsByDatabaseWindow(){long uc=voucher();var a=authorize(uc,0);var wrong=redeemBody(a).put("code","0".repeat(32));for(int n=0;n<5;n++)assertEquals(422,code(()->service.redeem(shop,key(),wrong)));assertEquals(429,code(()->service.redeem(shop,key(),redeemBody(a))));clock.value=clock.value.plusSeconds(600);var fresh=authorize(uc,1);service.redeem(shop,key(),redeemBody(fresh));assertEquals(1,count("coupon_service_redemption"));}
