 @Test void expiredTransportIdempotencyNeverCreatesAnotherOrderForSameIntent(){long uc=discount(),s=slot(2);String k=key();var b=CouponOrderInput.create(createBody(owner,s,uc).toString());var first=orders.createCoupon(owner,k,b);long o=first.path("data").path("order_id").longValue();orders.cancel(owner,key(),o);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE idempotency_key=?",k);var again=orders.createCoupon(owner,k,b);assertEquals(first.path("data"),again.path("data"));assertEquals(1,count("order"));assertEquals("AVAILABLE",couponState(uc));assertEquals("RELEASED",allocation(o));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE idempotency_key=?",k);var changed=createBody(owner,s,uc).put("vehicle_id",2);assertEquals(400,code(()->orders.createCoupon(owner,k,CouponOrderInput.create(changed.toString()))));assertEquals(1,count("order"));}
